INSERT INTO `ha_postmeta` (`post_id`,`meta_key`,`meta_value`) SELECT @translation_id,'_rank_math_description','تفاصيل شاملة حول تكلفة زراعة الشمندر السكري عبر شريط الطيبي في الهكتار، تحليل دقيق من حيث الجدوى الاقتصادية والفنية يهدف إلى توجيه المزارعين في العراق نحو اتخاذ قرارات مستنيرة. تضمن الدقة الفنية والأرقام الاقتصادية.' WHERE @translation_id IS NOT NULL AND NOT EXISTS (SELECT 1 FROM `ha_postmeta` WHERE post_id=@translation_id AND meta_key='_rank_math_description');
