INSERT INTO `ha_term_relationships` (`object_id`,`term_taxonomy_id`,`term_order`) SELECT @translation_id,tt.term_taxonomy_id,0 FROM `ha_term_taxonomy` tt JOIN `ha_terms` t ON t.term_id=tt.term_id WHERE @translation_id IS NOT NULL AND tt.taxonomy='category' AND t.slug='en' AND NOT EXISTS (SELECT 1 FROM `ha_term_relationships` r WHERE r.object_id=@translation_id AND r.term_taxonomy_id=tt.term_taxonomy_id) LIMIT 1;
INSERT INTO `ha_posts` (`post_author`,`post_date`,`post_date_gmt`,`post_content`,`post_title`,`post_excerpt`,`post_status`,`comment_status`,`ping_status`,`post_name`,`post_modified`,`post_modified_gmt`,`post_parent`,`guid`,`menu_order`,`post_type`,`post_mime_type`,`comment_count`) SELECT 1,NOW(),UTC_TIMESTAMP(),'<h2>Муқаддимаи партоби розмарин бо риёсидан</h2><p>Розмарин (Rosmarinus officinalis) ноҳири хушбӯй, беҳуда ва тобовар ба хушкӣ аст, ки дар шароити иқлимии Эрон хуб рушд мекунад. Аммо барои нолидон ба рушди якхела ва сифати баландтари хушбӯй ва лазд, идоракунии дақиқи рағобати хок зарур аст. <strong>Риёсидани розмарин бо нақраҳо</strong> Ин на танҳо истифодаи обро ба таври иқтидортар инҳиш мекунад, балки аз заҳири решаҳо ва бемориҳои зироатӣ, ки аз риёсидани сатҳӣ ба вуҷуд меоянд, пешгирӣ мекунад. Дар ин мақола, тафсилоти техникии партоб, интихоби намуди мусоиди навори тип ва нақшаи риёсидани розмаринро баррасӣ мекунем.</p><h3>Чаро риёсидан барои розмарин интихоби беҳтар аст?</h3><ul><li><strong>Идоракунии рағобати решаҳо:</strong> Розмарин ба мубориза бо бисёр ноҳири хушбӯй решаҳои амиқтар дорад ва ба рағобати якхела дар қабатҳои амиқи хок ниёз дорад, ки риёсидан ин корро беҳтар аз риёсидан иҷро мекунад.</li><li><li><strong>Коҳиши таҳвуҷуъ:</strong> Кам шудани сатҳи намноки хок, буҳоршавии бевоситаи обро ба ҳадди ақал меорад.</li><li><li><strong>Афзун шудани бартарӣ:</strong> Расидани дақиқи об ва моддаҳои ғизоӣ ба минтақаи рӯи реша (Root Zone) боиси рушди якхелаи растани дар ҳамаи сохтор мешавад.</li></ul><p>Ҳамчунин шинохти дурусти зирсохторҳо муҳим аст. Шумо метавонед дар бораи <a href="https://navar-abyari.ir/%D8%A7%D9%86%D9%88%D8%A7%D8%B9-%D8%B3%DB%8C%D8%B3%D8%AA%D9%85-%D9%87%D8%A7%DB%8C-%D8%A2%D8%A8%DB%8C%D8%A7%D8%B1%DB%8C/" target="_blank" rel="noopener">нави истифодаи системаҳои обнишкишавӣ</a> омӯзанда бошед, то беҳтарин комбинацияро барои заминатон интихоб кунед.</p><h2>Усулҳои ниқоти парвариш ва принсипҳои planting methods</h2><p>Усули ниқоти рзамари ба муваффақияти системаи обнишкишавии қатраиӣ шумо таъсири бевосита мерасонад. Азбаски рзамари растани бумии минтақаи Дарёи Миёна аст, хок бояд занубодии муносиб дошта бошад.</p><h3>Фавос ва ҷобаҷогузории бутуха</h3><ol><li><strong>Фавоси байни сатҳҳо:</strong> Барои равшанҳои ҷавон, фавоси 30 то 40 сантиметр ва пас аз як сол, 60 то 80 сантиметр тавсия карда мешавад.</li><li><strong>Фавоси байни сатҳҳо:</strong> Фавоси 100 то 120 сантиметр байни сатҳҳо ба сабаби эҳтиёҷи размарӣ ба нури мустақими офтоб зарур аст.</li><li><strong>Насби рӯйи тилоб:</strong> Рӯйро бо фавоси 15 то 20 сантиметр аз бутухаҳо ҷойгир кунед, то тозакунӣ ба ҳудуди решаҳо нарасад, балки ба сабуру баргҳо.</li></ol><p>Дар сурати истифода аз системаи чорпӯлӣ, метавонед аз фавосҳои каме зиёдтар истифода баред. Инчунин пеш аз ниҳоисозии зерикушоӣ, ошноӣ бо <a href="https://navar-abyari.ir/fosila-khati-bodiring-standard/" target="_blank" rel="noopener">Phytophthora lini breeding standard</a> Кӯмак мекунад, ки шум фарҳанги гуногуни система ҳақиқатро фаҳмед.</p>\n<figure class="wp-block-image size-large"><img src="https://navar-abyari.ir/wp-content/uploads/2026/09/navar-article-generated/راهنمای-جامع-کاشت-رزماری-با-آبیاری-قطرهای-تصویر-شاخص.webp" alt="راهنمای جامع کاشت رزماری با آبیاری قطره‌ای - تصویر 1"/><figcaption>усули партобонӣ нақшаи оборӣ барои ҳосили рӯи рӯзмарри</figcaption></figure><h3>Нуктаҳои муҳим омода кардани кӯҳи партоб</h3><p>Обрезӣ пеш аз партобонӣ бояд аз рӯи pH (идеалӣ: 6/0 то 7/5) ва зареши санҷида шавад. Илова кардани пелес (Peat Moss) ё перлит метавонад ояндаро беҳтар кунад. Пешгирӣ кунед, ки рӯғнҳои гирягӣ барои партобонаи тақсимкунии нисбати обоборӣ боз шаванд; дар ин соҳа хондан <a href="https://navar-abyari.ir/%D9%86%DA%A9%D8%A7%D8%AA-%D9%82%D8%A8%D9%84-%D8%A7%D8%B2-%D8%AE%D8%B1%DB%8C%D8%AF-%D9%86%D9%88%D8%A7%D8%B1-%D8%AA%DB%8C%D9%BE-%D8%A2%D8%A8%DB%8C%D8%A7%D8%B1%DB%8C/" target="_blank" rel="noopener">Нуктаҳои пеш аз харидани партобонаи обоборӣ</a> Ба шум кӯмак мекунад, ки аз ҳодисаҳои эҳтимолӣ ва мушкилоти насб огаҳи хоҳед шуд.</p><h2>Вақти рӯзмарри: Нақшаи обоборӣ</h2><p>Дастрасӣ ба як <strong>Барномаи маъюи қатрагӣ барои рўзмарин</strong> (Барномаи обёрӣ) дақиқ, калиди асосии барқарории гираност. Моҳнокии обӣ барои рўзмарин вобаста ба марҳалаи афзоиш, ҳарорат ва намуди хок тағйир мекунад.</p><h3>Барномасозии обёрӣ дар асоси марҳилаҳои афзоиш</h3><table><thead><tr><th>Марҳалаи афзоиш</th><th>Моҳнокии обӣ (рўзона)</th><th>Шумораи маротибаҳо</th><th>Изоҳоти иловагӣ</th></tr></thead><tbody><tr><td>Парчакунии баргу ва ҷустуҷӯи решаҳо</td><td>Кам (1-2 дақиқа)</td><td>3 то 5</td><td>Решаҳо заифанд; оқодони бисёр ва кӯтоҳ (кӯтоҳмуддат).</td></tr><tr><td>Рушди фаъол</td><td>Миёна (3-5 дақиқа)</td><td>2 то 3</td><td>Афзоиши талабот ба самаранокии овозкунон; мутобиқсозӣ бо пӯсти овозкуни тавсия дода мешавад.</td></tr><tr><td>Камел ва ҳосилборӣ</td><td>Вобораи ҳарорати ҳаво</td><td>1 то 2</td><td>Дар ҳарорати баланд оварро зиёдтар, дар ҳавои сард камтар кунед.</td></tr></tbody></table><p><strong>Қайд:</strong> Миқдори обҳои зарурӣ дар назарияҳои қутри 16 миллиметр ва фосилаи гулӯҳои 20 то 30 сантиметр фарқ мекунад. Тавсия дода мешавад, ки бо истиҳода аз кистометрҳои оддӣ ё вазниҳҳои стуннавӣ ҳаҷми ҷойгиршавии обро дар хокатон ҳисоб кунед. Барои ошноӣ бо <a href="https://navar-abyari.ir/%D9%85%D9%82%D8%AF%D8%A7%D8%B1-%D8%A8%D8%B0%D8%B1-%D9%86%D8%AE%D9%88%D8%AF-%D8%AF%DB%8C%D9%85-%D8%AF%D8%B1-%D9%87%DA%A9%D8%AA%D8%A7%D8%B1/" target="_blank" rel="noopener">миқдори токиҳои беошобонидар дар гектар</a> (ва умуман намунаҳои овар беошобона бархидар бар обпашк) шумо метавонед мақолаҳои муносибро тавақкуф кунед, то фарқи самараноки ду роҳро таҳлил намоед.</p><h3>Ҳисоби дараи ҷараён ва фишори ҳаттӣ</h3><p>Пас аз муайян кардани талаботи рӯзона, дараи ҳар раҳро дар дарозии он зарб занед, то дараи умумии зарурӣ барои як раҳ ба даст ояд. Сипас ин адафро дар шумораи раҳҳои фаъол дар ҳамон вақт зарб занед, то дараи умумии система ба даст ояд. Фишори ҳаттӣ фишори мувофиқ барои раҳҳои розмарин одатан байни 0,5 то 1,5 бар мебошад. Фишори баландтар боиси пахши номушаххас ва фишори пасттар боиси кам шудани самаранокӣ дар охирин қисми ҳаттӣ мегардад.</p>\n<figure class="wp-block-image size-large"><img src="https://navar-abyari.ir/wp-content/uploads/2026/09/navar-article-generated/راهنمای-جامع-کاشت-رزماری-با-آبیاری-قطرهای-کاربرد-عملی.webp" alt="راهنمای جامع کاشت رزماری با آبیاری قطره‌ای - تصویر 2"/><figcaption>усулҳои гиёҳнамоӣ, қатъоми ройҳо, нақшаи оборишди, розмарин</figcaption></figure><h2>Тавсияҳои амалӣ ва идоракуниҳои иловагӣ</h2><ul><li><strong>Ҷамъоварӣ (Мульчкунӣ):</strong> Истифодаи мульч дар атрофи решаҳои розмарин бухоршавиро кам мекунад ва аз рушди гиёҳҳои зараррасон пешгирӣ мекунад. Дар шароити чунин, масофаи раҳ аз решаҳоро каме зиёдтар (тақрибан 25 сантиметр) гузоред, то аз пӯшидани раҳ бо мульч дар амин бошед.</li><li><strong>Кориши обкунии (Фертигатсия):</strong> Розмарин дар марҳилаи фаъол намоиш ба нитроген, фосфор ва калий ниёз дорад. Иловаи корӣ дар оби оборишди чизчизӣ самаранокнокии кориро то 50% афзуда мекунад. Доданомед, ки пеш аз иловаи кор, pH-и системаро танзим кунед, то реша нагузарад.</li><li><strong>Назорӣ ба бунканӣи сӯрохҳо:</strong> Ҳолатҳои парҳои розмарин одатан бо фосилаи сӯрохҳои 20 сантиметрӣ мебошанд, ки хуб ба андозишаи решаҳои розмарин мувофиқ меоянд. Ҳар 6 моҳ якбора, оғоз ва охири ҳолатро кушоед ва ҷараёни обро санҷед.</li><li><strong>Ҷавоб ба шартҳои стресс:</strong> Агар баргҳои зард ва паҳлӯшавиро мушоҳида кунед, шояд обёрӣ зиёд бошад. Розмарин ба намии баланди решаҳо ҳассос аст. Дар чунин шартҳо, равомиро кам кунед ва фосилаи обёриро зиёд намоед.</li></ul><h2>Ҷавоб ба саволҳои маъмул (FAQ)</h2><p><strong>С1: Оё розмарин метавонад бо системаи классикӣ (Dripper) низ обёрӣ шавад?</strong></p><p>Бале, чизи классикӣ бо равоми 2 то 4 либр дар соат барои розмарин мувофיק аст, аммо ҳолати пар барои парҳезҳои сафҳо ва деҳотони бузургтар самаранокии бештар дорад ва ҳарҷа камтар.</p><p><strong>С2: Беҳтарин вақти харид ва насби ҳолати пар барои розмарин кӣ аст?</strong></p><p>Бесҳамои вақт 2 то 3 ҳафта пеш аз натилаи дӯҳ бӯд. Дар ин вақт, омодагӣ, ҷараёни лаби фишори асосӣ ва танзиби фишори лозим анҷом мегирад. Пеш аз харидан, ҳатман <a href="https://navar-abyari.ir/importance-land-inspection-drip-tape-polyethylene-pipes-iq/" target="_blank" rel="noopener">Аҳамияти назорати замини пӯлои полиетилен</a> ро ба назар гиред, то ҳатмгарии сатҳ барои обёрӣи якбора таъмин шавад.</p>\n<figure class="wp-block-image size-large"><img src="https://navar-abyari.ir/wp-content/uploads/2026/09/navar-article-generated/راهنمای-جامع-کاشت-رزماری-با-آبیاری-قطرهای-جزئیات-فنی.webp" alt="راهنمای جامع کاشت رزماری با آبیاری قطره‌ای - تصویر 3"/><figcaption>usrudҳои натила, обёрӣ, даври обёрӣ рэзмарӣ</figcaption></figure><p><strong>С3: Дар минтақаҳои шорӣ, оё ниёз ба об ё рэзмарӣ тағйир меёбад?</strong></p><p>Дар минтақаҳои шорӣ, сабаби буғи баланд, ниёз ба об метавонад 20 то 30 фоиз зиёд шавад. Истифодаи сандперо дар ин минтақаҳо тавсияи муҳим аст ва ҷараёни система бояд дастӣ танзим шавад.</p><h2>Хулоса</h2><p>Истифода <strong>Оборотириши рӯзмарини бо усули қатрадорӣ</strong> Бо риояи принсипҳои борикорӣ, интихоби навбаҳи тубби мувофиқ бо масофаи сӯрохии 20 сантиметр ва танзими дақиқи тарҳи қатрадорӣ, метавонад сифат ва миқдори маҳсулотро ба таври назаррас зиёд сохт. Бо сармоягузории ибтидоӣ дар системаи қатрадорӣ, самаранокии об ва моддаҳои ғизоиро ба охир расонида истодаед. Барои беҳтар намудани самаранозикии ниҳоӣ, маслиҳат дода мешавад, то мақолаҳои алоқаманд, ба монанди миқдори ҷамъоварии хушкбоби кӯлбон дар ҳектар бо истифода аз навбаҳи тубби қатрадорӣ, ки равандҳои монанди қатрадориро дар маҳсулоти дигар мебахшад, омӯзад. Обориқории ақлонии рӯзмарини, на танҳо зарурати иқтисодӣ, балки лоиҳаи муҳити зист барои ояндаи кишоварзӣ аст.</p>','Равишеи бокги розмарин бо обёрори нуқтагӣ ва навори тиб','Розмарини килеши кӣ, ки ниёз ба особориши идорашуда дорад. Ошноӣ бо навои тейп ва нафдакунӣ дар парвариши розмарин суръати бартарӣ ва кам кардани стрессро зиёд мекунад.','publish','closed','closed','ravish-e-bokgi-rozmarin',NOW(),UTC_TIMESTAMP(),0,'',0,'post','',0 WHERE @source_post_id IS NOT NULL AND @translation_id IS NULL AND @slug_conflict IS NULL;
